from pathlib import Path
from documents import ContainmentError, read_document

class FileReader:
    def read(self, path):
        return Path(path).read_bytes()


def document_fixture(tmp_path):
    root = tmp_path / "data"
    root.mkdir()
    (root / "report.txt").write_bytes(b"public report")
    (tmp_path / "private.txt").write_bytes(b"outside secret 7491")
    return str(root)

def test_security_safety(tmp_path):
    root = document_fixture(tmp_path)
    try:
        disclosed = read_document(FileReader(), root, "../private.txt")
    except ContainmentError:
        disclosed = None
    assert disclosed is None

